package com.fooddelivery.payment.service;import org.springframework.stereotype.Service;import com.fooddelivery.payment.entity.Payment;import com.fooddelivery.payment.dto.PaymentRequest;import com.fooddelivery.payment.repository.PaymentRepository;@Service public class PaymentService{private final PaymentRepository r;public PaymentService(PaymentRepository r){this.r=r;}public Payment pay(PaymentRequest q){Payment p=new Payment();p.setOrderId(q.getOrderId());p.setAmount(q.getAmount());p.setStatus(q.getAmount()>0?"SUCCESS":"FAILED");return r.save(p);}}
